  1	package com.fream.back.domain.order.controller.command;
  2	
  3	import com.fream.back.domain.order.dto.InstantOrderRequestDto;
  4	import com.fream.back.domain.order.dto.OrderBidRequestDto;
  5	import com.fream.back.domain.order.exception.*;
  6	import com.fream.back.domain.order.service.command.OrderBidCommandService;
  7	import com.fream.back.domain.payment.dto.PaymentRequestDto;
  8	import com.fream.back.global.dto.ResponseDto;
  9	import com.fream.back.global.utils.SecurityUtils;
 10	import jakarta.validation.Valid;
 11	import lombok.RequiredArgsConstructor;
 12	import lombok.extern.slf4j.Slf4j;
 13	import org.springframework.http.ResponseEntity;
 14	import org.springframework.validation.annotation.Validated;
 15	import org.springframework.web.bind.annotation.*;
 16	
 17	
 18	/**
 19	 * 주문 입찰 명령 컨트롤러
 20	 */
 21	@RestController
 22	@RequestMapping("/order-bids")
 23	@RequiredArgsConstructor
 24	@Slf4j
 25	@Validated
 26	public class OrderBidCommandController {
 27	
 28	    private final OrderBidCommandService orderBidCommandService;
 29	
 30	    /**
 31	     * 주문 입찰을 생성합니다.
 32	     *
 33	     * @param requestDto 주문 입찰 요청 정보
 34	     * @return 생성된 주문 입찰 ID
 35	     * @throws OrderBidAccessDeniedException 주문 입찰에 대한 접근 권한이 없는 경우
 36	     * @throws InvalidOrderBidDataException 주문 입찰 정보가 유효하지 않은 경우
 37	     * @throws OrderBidCreationFailedException 주문 입찰 생성 실패 시
 38	     */
 39	    @PostMapping
 40	    public ResponseEntity<ResponseDto<Long>> createOrderBid(@RequestBody @Valid OrderBidRequestDto requestDto) {
 41	        // 사용자 이메일 추출 및 검증
 42	        String email = SecurityUtils.extractAndValidateEmailForOrderBid("주문 입찰 생성");
 43	
 44	        log.info("사용자 [{}]가 상품 사이즈(ID: {})에 대한 주문 입찰을 생성합니다. 입찰 가격: {}",
 45	                email, requestDto.getProductSizeId(), requestDto.getBidPrice());
 46	
 47	        // 서비스 호출
 48	        Long orderBidId = orderBidCommandService.createOrderBid(
 49	                email,
 50	                requestDto.getProductSizeId(),
 51	                requestDto.getBidPrice()
 52	        ).getId();
 53	
 54	        return ResponseEntity.ok(ResponseDto.success(orderBidId, "주문 입찰이 성공적으로 생성되었습니다."));
 55	    }
 56	
 57	    /**
 58	     * 주문 입찰을 삭제합니다.
 59	     *
 60	     * @param orderBidId 주문 입찰 ID
 61	     * @return 응답 엔티티
 62	     * @throws OrderBidNotFoundException 주문 입찰을 찾을 수 없는 경우
 63	     * @throws OrderBidAlreadyMatchedException 이미 매칭된 주문 입찰인 경우
 64	     * @throws OrderBidDeletionFailedException 주문 입찰 삭제 실패 시
 65	     */
 66	    @DeleteMapping("/{orderBidId}")
 67	    public ResponseEntity<ResponseDto<Void>> deleteOrderBid(@PathVariable("orderBidId") Long orderBidId) {
 68	        // 사용자 이메일 추출 및 검증
 69	        String email = SecurityUtils.extractAndValidateEmailForOrderBid("주문 입찰 삭제");
 70	
 71	        log.info("사용자 [{}]가 주문 입찰(ID: {})의 삭제를 요청합니다.", email, orderBidId);
 72	
 73	        // 서비스 호출
 74	        orderBidCommandService.deleteOrderBid(orderBidId);
 75	
 76	        return ResponseEntity.ok(ResponseDto.success(null, "주문 입찰이 성공적으로 삭제되었습니다."));
 77	    }
 78	
 79	    /**
 80	     * 즉시 구매 입찰을 생성합니다.
 81	     *
 82	     * @param requestDto 즉시 구매 요청 정보
 83	     * @return 생성된 주문 ID
 84	     * @throws OrderBidAccessDeniedException 주문 입찰에 대한 접근 권한이 없는 경우
 85	     * @throws InvalidOrderBidDataException 주문 입찰 정보가 유효하지 않은 경우
 86	     * @throws SaleBidNotFoundException 판매 입찰을 찾을 수 없는 경우
 87	     * @throws OrderBidCreationFailedException 주문 입찰 생성 실패 시
 88	     */
 89	    @PostMapping("/instant")
 90	    public ResponseEntity<ResponseDto<Long>> createInstantOrderBid(@RequestBody @Valid InstantOrderRequestDto requestDto) {
 91	        // 사용자 이메일 추출 및 검증
 92	        String email = SecurityUtils.extractAndValidateEmailForOrderBid("즉시 구매 입찰 생성");
 93	
 94	        log.info("사용자 [{}]가 판매 입찰(ID: {})에 대한 즉시 구매를 요청합니다. 창고 보관 여부: {}",
 95	                email, requestDto.getSaleBidId(), requestDto.isWarehouseStorage());
 96	
 97	        // 결제 정보 보강
 98	        PaymentRequestDto paymentRequest = enrichPaymentRequest(requestDto.getPaymentRequest(), email);
 99	
100	        // 서비스 호출
101	        Long orderId = orderBidCommandService.createInstantOrderBid(
102	                email,
103	                requestDto.getSaleBidId(),
104	                requestDto.getAddressId(),
105	                requestDto.isWarehouseStorage(),
106	                paymentRequest
107	        ).getId();
108	
109	        return ResponseEntity.ok(ResponseDto.success(orderId, "즉시 구매가 성공적으로 처리되었습니다."));
110	    }
111	
112	    /**
113	     * 결제 요청 정보를 보강합니다.
114	     *
115	     * @param paymentRequest 결제 요청 정보
116	     * @param email 사용자 이메일
117	     * @return 보강된 결제 요청 정보
118	     */
119	    private PaymentRequestDto enrichPaymentRequest(PaymentRequestDto paymentRequest, String email) {
120	        paymentRequest.setUserEmail(email);
121	        paymentRequest.setOrderId(null); // 초기에는 null로 설정, 이후 Order 생성 후 업데이트 가능
122	        return paymentRequest;
123	    }
