    40	
    41	    /**
    42	     * 단일 사용자 알림 생성
    43	     */
    44	    public NotificationDTO createNotification(Long userId, NotificationCategory category, NotificationType type, String message) {
    45	        try {
    46	            User user = userRepository.findById(userId)
    47	                    .orElseThrow(() -> new NotificationException(
    48	                            NotificationErrorCode.NOTIFICATION_USER_NOT_FOUND,
    49	                            "사용자 ID: " + userId + "를 찾을 수 없습니다."
    50	                    ));
    51	
    52	            Notification notification = buildNotification(user, category, type, message);
    53	            Notification savedNotification = notificationRepository.save(notification);
    54	            log.info("알림 생성 완료: 사용자={}, 카테고리={}, 타입={}", user.getEmail(), category, type);
    55	
    56	            // 실시간 알림 전송 시도
    57	            sendRealTimeNotification(user.getEmail(), toDTO(savedNotification));
    58	
    59	            return toDTO(savedNotification);
    60	        } catch (NotificationException e) {
    61	            throw e; // 이미 NotificationException이면 그대로 전파
    62	        } catch (Exception e) {
    63	            log.error("알림 생성 중 오류 발생: 사용자ID={}, 카테고리={}, 타입={}, 오류={}",
    64	                    userId, category, type, e.getMessage(), e);
    65	            throw new NotificationException(NotificationErrorCode.NOTIFICATION_CREATION_FAILED, e);
    66	        }
    67	    }
    68	
    69	    /**
    70	     * 모든 사용자 알림 생성
    71	     */
    72	    public List<NotificationDTO> createNotificationForAll(NotificationRequestDTO requestDTO) {
    73	        try {
    74	            List<User> allUsers = userRepository.findAll();
    75	            if (allUsers.isEmpty()) {
    76	                log.warn("알림 대상 사용자가 없습니다.");
    77	                return List.of();
    78	            }
    79	
    80	            log.info("전체 사용자 알림 생성 시작: 카테고리={}, 타입={}, 대상 사용자 수={}",
    81	                    requestDTO.getCategory(), requestDTO.getType(), allUsers.size());
    82	
    83	            List<Notification> notifications = createNotificationsForUsers(
    84	                    allUsers, requestDTO.getCategory(), requestDTO.getType(), requestDTO.getMessage());
    85	
    86	            List<Notification> savedNotifications = notificationRepository.saveAll(notifications);
    87	            log.info("전체 사용자 알림 생성 완료: 카테고리={}, 타입={}, 생성된 알림 수={}",
    88	                    requestDTO.getCategory(), requestDTO.getType(), savedNotifications.size());
    89	
    90	            // 연결된 사용자에게만 실시간 알림 전송
    91	            broadcastNotificationsToConnectedUsers(allUsers, savedNotifications);
    92	
    93	            return toDTOList(savedNotifications);
    94	        } catch (Exception e) {
    95	            log.error("전체 사용자 알림 생성 중 오류 발생: 카테고리={}, 타입={}, 오류={}",
