   104	    public void markAsRead(Long notificationId, String email) {
   105	        try {
   106	            Notification notification = notificationRepository.findById(notificationId)
   107	                    .orElseThrow(() -> new NotificationException(
   108	                            NotificationErrorCode.NOTIFICATION_NOT_FOUND,
   109	                            "알림 ID: " + notificationId + "를 찾을 수 없습니다."
   110	                    ));
   111	
   112	            // 알림의 사용자 이메일과 요청한 이메일이 일치하는지 확인
   113	            if (!notification.getUser().getEmail().equals(email)) {
   114	                log.warn("알림 읽음 처리 권한 없음: 알림ID={}, 요청자={}, 소유자={}",
   115	                        notificationId, email, notification.getUser().getEmail());
   116	                throw new NotificationException(
   117	                        NotificationErrorCode.NOTIFICATION_ACCESS_DENIED,
   118	                        "해당 알림은 현재 사용자에게 속하지 않습니다."
